import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { Trash2, CheckCircle, ChevronLeft } from 'lucide-react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';
import CheckoutForm from './CheckoutForm';

// Paste your PUBLISHABLE key here
const stripePromise = loadStripe('pk_test_51UKVj23kaKAmRKqK4qdVvverkj21WVv3RTuPdYuyYVVLKvGBwGhwMV6n1Nt4qi2vuRH3z3tERIyWZXSjL6wP9m7r00zwnpRQIE');

function Cart({ cart, removeFromCart, user, placeOrder }) {
  const [checkoutStep, setCheckoutStep] = useState('cart');
  const [clientSecret, setClientSecret] = useState('');
  const navigate = useNavigate();

  const total = cart.reduce((sum, item) => sum + parseFloat(item.price), 0);

  const handleProceedToPayment = async () => {
    if (!user) {
      alert('Please log in to proceed.');
      return navigate('/login');
    }
    
    // Ask Flask to create a real Stripe payment intent
    try {
      const response = await axios.post('http://127.0.0.1:5000/api/create-payment-intent', { total });
      setClientSecret(response.data.clientSecret);
      setCheckoutStep('payment');
    } catch (error) {
      console.error("Payment initiation failed:", error);
      alert("Could not connect to payment gateway.");
    }
  };

  const handlePaymentSuccess = () => {
    setCheckoutStep('success');
    placeOrder(total);
  };

  if (checkoutStep === 'success') {
    return (
      <div className="max-w-lg mx-auto mt-16 p-8 bg-white rounded-2xl shadow-lg text-center">
        <CheckCircle size={48} className="text-green-600 mx-auto mb-4" />
        <h2 className="text-3xl font-bold mb-2">Payment Successful!</h2>
        <p className="text-gray-600 mb-8">Your real transaction is complete.</p>
        <button onClick={() => navigate('/profile')} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold w-full">
          View Orders
        </button>
      </div>
    );
  }

  if (checkoutStep === 'payment' && clientSecret) {
    const options = { clientSecret };
    return (
      <div className="max-w-lg mx-auto mt-10">
        <button onClick={() => setCheckoutStep('cart')} className="flex items-center text-blue-600 mb-4">
          <ChevronLeft size={20} /> Back to Cart
        </button>
        <h2 className="text-2xl font-bold mb-6">Secure Checkout</h2>
        
        {/* Stripe Elements Provider wraps the checkout form */}
        <Elements stripe={stripePromise} options={options}>
          <CheckoutForm total={total} onSuccess={handlePaymentSuccess} />
        </Elements>
      </div>
    );
  }

  // Standard Cart View (Unchanged logic, simplified for brevity)
  return (
    <div className="max-w-4xl mx-auto mt-10 bg-white p-8 rounded-lg shadow-md">
      <h2 className="text-3xl font-bold mb-6 border-b pb-4">Shopping Cart</h2>
      
      {cart.length === 0 ? (
        <p className="text-center text-gray-500 font-bold mt-10">Your cart is empty.</p>
      ) : (
        <>
          <div className="space-y-4">
            {cart.map((item, index) => (
              <div key={index} className="flex justify-between items-center bg-gray-50 p-4 rounded border">
                <span className="font-bold">{item.name} - ${parseFloat(item.price).toFixed(2)}</span>
                <button onClick={() => removeFromCart(index)} className="text-red-500"><Trash2 size={20} /></button>
              </div>
            ))}
          </div>
          <div className="mt-8 border-t pt-4">
            <h3 className="text-2xl font-bold mb-6">Total: ${total.toFixed(2)}</h3>
            <button onClick={handleProceedToPayment} className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold">
              Proceed to Secure Payment
            </button>
          </div>
        </>
      )}
    </div>
  );
}

export default Cart;
